-- Схема, которую EF Core (Npgsql) создаёт по модели из темы p3-efcore, плюс те же учебные данные, что и в library.sql.
-- Используется tools/verify_sql.py как шаблон БД для страниц EF Core (p3-efcore … p3-repository).
CREATE TABLE "Authors" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Name" text NOT NULL
);
CREATE TABLE "Books" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Isbn" character varying(20) NOT NULL,
    "Title" character varying(300) NOT NULL,
    "Genre" text NOT NULL,
    "Year" integer NOT NULL,
    "Copies" integer NOT NULL,
    CONSTRAINT "CK_Books_Copies" CHECK ("Copies" >= 0)
);
CREATE UNIQUE INDEX "IX_Books_Isbn" ON "Books" ("Isbn");
CREATE TABLE "Readers" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "FullName" text NOT NULL,
    "CardNumber" text NOT NULL,
    "Type" text NOT NULL
);
CREATE UNIQUE INDEX "IX_Readers_CardNumber" ON "Readers" ("CardNumber");
CREATE TABLE "Loans" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "BookId" integer NOT NULL,
    "ReaderId" integer NOT NULL,
    "LoanedAt" date NOT NULL,
    "DueAt" date NOT NULL,
    "ReturnedAt" date,
    CONSTRAINT "FK_Loans_Books_BookId" FOREIGN KEY ("BookId") REFERENCES "Books" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_Loans_Readers_ReaderId" FOREIGN KEY ("ReaderId") REFERENCES "Readers" ("Id") ON DELETE RESTRICT
);
CREATE INDEX "IX_Loans_BookId" ON "Loans" ("BookId");
CREATE INDEX "IX_Loans_ReaderId" ON "Loans" ("ReaderId");
CREATE TABLE "AuthorBook" (
    "AuthorsId" integer NOT NULL,
    "BooksId" integer NOT NULL,
    CONSTRAINT "PK_AuthorBook" PRIMARY KEY ("AuthorsId", "BooksId"),
    CONSTRAINT "FK_AuthorBook_Authors_AuthorsId" FOREIGN KEY ("AuthorsId") REFERENCES "Authors" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_AuthorBook_Books_BooksId" FOREIGN KEY ("BooksId") REFERENCES "Books" ("Id") ON DELETE CASCADE
);
CREATE INDEX "IX_AuthorBook_BooksId" ON "AuthorBook" ("BooksId");

